diff --git a/src/pcre2posix.c b/src/pcre2posix.c
index 2f2cdf54..ffeb1647 100644
--- a/src/pcre2posix.c
+++ b/src/pcre2posix.c
@@ -411,7 +411,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     if (pmatch[0].rm_so < 0 || pmatch[0].rm_eo < 0 || pmatch[0].rm_so > pmatch[0].rm_eo)
       return REG_INVARG;
     so = (PCRE2_SIZE)pmatch[0].rm_so;
-    eo = (PCRE2_SIZE)pmatch[0].rm_eo;
+    eo = (PCRE2_SIZE)pmatch[0].rm_eo - so;
   }
   else
   {
@@ -419,7 +419,10 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     eo = strlen(string);
   }

-  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string + so, (eo - so), 0,
+  /* Run the match on the subject range selected above. The start offset is
+  applied to the subject pointer rather than passed as a starting offset. */
+
+  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string + so, eo, 0,
                    options, md, NULL);

   /* Successful match */

diff --git a/src/pcre2posix.c b/src/pcre2posix.c
index 221fc3aa..15fe4816 100644
--- a/src/pcre2posix.c
+++ b/src/pcre2posix.c
@@ -406,24 +406,11 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t

   md = (pcre2_match_data *)preg->re_match_data;

-  if ((eflags & REG_NOTBOL) != 0)
-    options |= PCRE2_NOTBOL;
-  if ((eflags & REG_NOTEOL) != 0)
-    options |= PCRE2_NOTEOL;
-  if ((eflags & REG_NOTEMPTY) != 0)
-    options |= PCRE2_NOTEMPTY;
-
-  /* When REG_NOSUB was specified, or if no vector has been passed in which to
-  put captured strings, ensure that nmatch is zero. This will stop any attempt to
-  write to pmatch. */
-
-  if ((preg->re_cflags & REG_NOSUB) != 0 || pmatch == NULL)
-    nmatch = 0;
-
   /* REG_STARTEND is a BSD extension, to allow for non-NUL-terminated strings.
   The man page from OS X says "REG_STARTEND affects only the location of the
   string, not how it is matched". That is why the "so" value is used to bump the
-  start location rather than being passed as a PCRE2 "starting offset". */
+  start location rather than being passed as a PCRE2 "starting offset". The
+  range is validated together with the other arguments, before use. */

   if ((eflags & REG_STARTEND) != 0)
   {
@@ -432,7 +419,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     if (pmatch[0].rm_so < 0 || pmatch[0].rm_eo < 0 || pmatch[0].rm_so > pmatch[0].rm_eo)
       return REG_INVARG;
     so = (PCRE2_SIZE)pmatch[0].rm_so;
-    eo = (PCRE2_SIZE)pmatch[0].rm_eo - so;
+    eo = (PCRE2_SIZE)pmatch[0].rm_eo;
   }
   else
   {
@@ -440,6 +427,20 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     eo = strlen(string);
   }

+  if ((eflags & REG_NOTBOL) != 0)
+    options |= PCRE2_NOTBOL;
+  if ((eflags & REG_NOTEOL) != 0)
+    options |= PCRE2_NOTEOL;
+  if ((eflags & REG_NOTEMPTY) != 0)
+    options |= PCRE2_NOTEMPTY;
+
+  /* When REG_NOSUB was specified, or if no vector has been passed in which to
+  put captured strings, ensure that nmatch is zero. This will stop any attempt to
+  write to pmatch. */
+
+  if ((preg->re_cflags & REG_NOSUB) != 0 || pmatch == NULL)
+    nmatch = 0;
+
   /* Run the match on the subject range selected above. The start offset is
   applied to the subject pointer rather than passed as a starting offset. */
